#!/usr/bin/env bash
set -euo pipefail

# Serialize the two final Retrieval runs from a final candidate pool and its
# deep cross-encoder reranked prefix. Intermediate pools are generated by the
# TypeScript pipeline and tools/deep_ce_rerank.py; they are not committed.

CODE_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$CODE_ROOT"

: "${RUN_DIR:?Set RUN_DIR to the final Retrieval run directory}"

PYTHON="${PYTHON:-python3}"
POOL="${POOL:-$RUN_DIR/candidate_pool_top5000.trec}"
DEEP_POOL="${DEEP_POOL:-$RUN_DIR/deepce/candidate_pool_top5000.trec}"
OUT="${OUT:-$CODE_ROOT/out/retrieval-submissions}"
UNC_TAG="${UNC_TAG:-cfda-vfs-unc}"
DEEP_TAG="${DEEP_TAG:-cfda-vfs-deep}"

for required in "$POOL" "$DEEP_POOL"; do
  [[ -s "$required" ]] || { echo "Missing input: $required" >&2; exit 1; }
done

mkdir -p "$OUT"
merged="$OUT/.deep_merged.trec"
"$PYTHON" tools/merge_deep_tail.py "$POOL" "$DEEP_POOL" --out "$merged"

emit() {
  local tag="$1"
  local ranking="$2"
  local output_dir="$OUT/$tag"
  mkdir -p "$output_dir"
  "$PYTHON" tools/apply_deep_cut.py "$POOL" "$ranking" --max 5000 \
    --out "$output_dir/r_output_trec_rag_2026.tsv" --tag "$tag"
}

emit "$UNC_TAG" "$POOL"
emit "$DEEP_TAG" "$merged"

echo "Final Retrieval outputs:"
echo "  $OUT/$UNC_TAG/r_output_trec_rag_2026.tsv"
echo "  $OUT/$DEEP_TAG/r_output_trec_rag_2026.tsv"
